<?php require_once __DIR__.'/_resposta.php'; exigirMetodo('POST'); require_once __DIR__.'/../config/conexao.php';$d=receberJson();$email=strtolower(trim($d['email']??''));$senha=$d['senha']??'';if(!filter_var($email,FILTER_VALIDATE_EMAIL)||$senha==='')responder(['sucesso'=>false,'mensagem'=>'Informe e-mail e senha.'],422);$q=$pdo->prepare('SELECT id,nome,email,senha_hash FROM usuarios WHERE email=? LIMIT 1');$q->execute([$email]);$u=$q->fetch();if(!$u||!password_verify($senha,$u['senha_hash']))responder(['sucesso'=>false,'mensagem'=>'E-mail ou senha incorretos.'],401);session_regenerate_id(true);$_SESSION['usuario_id']=(int)$u['id'];$_SESSION['usuario_nome']=$u['nome'];responder(['sucesso'=>true,'mensagem'=>'Login realizado com sucesso.','usuario'=>['id'=>(int)$u['id'],'nome'=>$u['nome']]]);
